/* CPU Quest: level content. Every challenge is grounded in the computer-organization lecture guide. */
const { rnd, pick, fmt, shuffle } = Kit;
const pre = s => '<pre class="code">' + s + '</pre>';
const REGN = { t: 8, s: 16, a: 4, v: 2 };
const bin = (v, n) => v.toString(2).padStart(n, '0');

// generator for pipeline-cycle questions: 5-stage pipeline, full forwarding, hardware load-use stall
function codeGen(force) {
  for (;;) {
    const regs = ['$1', '$2', '$3', '$4', '$5', '$6'];
    const n = rnd(4, 6), ins = [];
    for (let i = 0; i < n; i++) {
      const k = Math.random() < 0.4 ? 'lw' : pick(['add', 'sub', 'and']);
      const d = pick(regs), a = pick(regs), b = pick(regs);
      ins.push(k === 'lw' ? { k, d, a } : { k, d, a, b });
    }
    let st = 0;
    for (let i = 0; i < n - 1; i++) if (ins[i].k === 'lw') { const nx = ins[i + 1], rd = nx.k === 'lw' ? [nx.a] : [nx.a, nx.b]; if (rd.includes(ins[i].d)) st++; }
    if (force && st === 0) continue;
    if (!force && st > 1) continue;
    const txt = ins.map(x => x.k === 'lw' ? 'lw ' + x.d + ', 0(' + x.a + ')' : x.k + ' ' + x.d + ', ' + x.a + ', ' + x.b).join('\n');
    return { txt, st, n };
  }
}
const cyc = force => ({ t: 'num', tier: 3, boss: force === 1, gen() {
  const g = codeGen(force); const ans = g.n + 4 + g.st;
  return { q: 'A 5-stage pipeline has full forwarding plus a hardware stall for the load-use case. Nothing else stalls. In which clock cycle does the <b>last</b> instruction finish (write back)?' + pre(g.txt), a: ans, tol: 0, abs: 0.01, hint: 'With no stalls, instruction n finishes in cycle n + 4. A lw followed right away by an instruction that reads its register costs one extra cycle.', why: g.n + ' instructions finish in cycle ' + (g.n + 4) + ' with no stalls. ' + g.st + ' load-use stall' + (g.st === 1 ? '' : 's') + ' add' + (g.st === 1 ? 's' : '') + ' ' + g.st + ', so the last one finishes in cycle ' + ans + '.' };
} });

